**Plan**
- A static Keybinds class stores and loads KeyCode bindings for jump, sprint and interact from PlayerPrefs.
- The menu shows one button per action; clicking it enters a listening state that reads the next key press in Update (Escape cancels).
- The new key is saved immediately and the button text is refreshed.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;

public static class Keybinds
{
    private static readonly Dictionary<string, KeyCode> Defaults = new Dictionary<string, KeyCode>
    {
        { "Jump", KeyCode.Space },
        { "Sprint", KeyCode.LeftShift },
        { "Interact", KeyCode.E },
    };

    public static IEnumerable<string> Actions
    {
        get { return Defaults.Keys; }
    }

    public static KeyCode Get(string action)
    {
        KeyCode fallback = Defaults[action];
        int stored = PlayerPrefs.GetInt("Keybind." + action, (int)fallback);
        return (KeyCode)stored;
    }

    public static void Set(string action, KeyCode key)
    {
        PlayerPrefs.SetInt("Keybind." + action, (int)key);
        PlayerPrefs.Save();
    }
}

public class KeyRebindMenuUI : MonoBehaviour
{
    private readonly Dictionary<string, Button> buttons = new Dictionary<string, Button>();
    private Label statusLabel;
    private string listeningAction;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.style.flexGrow = 1;
        root.style.alignItems = Align.Center;
        root.style.justifyContent = Justify.Center;
        root.style.backgroundColor = new Color(0.08f, 0.09f, 0.13f, 1f);

        Label title = new Label("Controls");
        title.style.fontSize = 56;
        title.style.color = Color.white;
        title.style.marginBottom = 30;
        root.Add(title);

        buttons.Clear();
        foreach (string action in Keybinds.Actions)
        {
            string captured = action;
            VisualElement row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 12;

            Label name = new Label(action);
            name.style.width = 200;
            name.style.fontSize = 32;
            name.style.color = Color.white;
            row.Add(name);

            Button button = new Button(() => BeginListening(captured));
            button.text = Keybinds.Get(action).ToString();
            button.style.width = 260;
            button.style.height = 56;
            button.style.fontSize = 28;
            row.Add(button);
            buttons[action] = button;
            root.Add(row);
        }

        statusLabel = new Label("Click an action, then press a key");
        statusLabel.style.fontSize = 24;
        statusLabel.style.color = new Color(0.7f, 0.75f, 0.85f, 1f);
        statusLabel.style.marginTop = 20;
        root.Add(statusLabel);
    }

    private void BeginListening(string action)
    {
        listeningAction = action;
        buttons[action].text = "Press a key...";
        statusLabel.text = "Press a key for " + action + " (Esc to cancel)";
    }

    private void Update()
    {
        if (listeningAction == null || !Input.anyKeyDown) return;

        string action = listeningAction;
        listeningAction = null;
        if (!Input.GetKeyDown(KeyCode.Escape))
        {
            foreach (KeyCode key in Enum.GetValues(typeof(KeyCode)))
            {
                if (key == KeyCode.None || key >= KeyCode.Mouse0) continue;
                if (Input.GetKeyDown(key))
                {
                    Keybinds.Set(action, key);
                    break;
                }
            }
        }

        buttons[action].text = Keybinds.Get(action).ToString();
        statusLabel.text = action + " is bound to " + Keybinds.Get(action);
    }
}
```

Game scripts read bindings with `Input.GetKeyDown(Keybinds.Get("Jump"))`. When a binding button is clicked the menu waits in Update for the next key press, skipping mouse buttons, and Escape cancels without changing anything. Each accepted key is written to PlayerPrefs immediately and the button text is refreshed from the saved value.

