using UnityEngine;
using UnityEngine.UIElements;

public class AmmoCounterUI : MonoBehaviour
{
    [SerializeField] private int magazineSize = 30;
    [SerializeField] private float lowAmmoFraction = 0.25f;
    [SerializeField] private float reloadTime = 1.5f;

    private Label ammoLabel;
    private Label hintLabel;
    private IVisualElementScheduledItem flasher;
    private bool flashOn;
    private int current;
    private float reloadTimer;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.pickingMode = PickingMode.Ignore;

        VisualElement panel = new VisualElement();
        panel.style.position = Position.Absolute;
        panel.style.right = 50;
        panel.style.bottom = 40;
        panel.style.alignItems = Align.FlexEnd;
        root.Add(panel);

        ammoLabel = new Label();
        ammoLabel.style.fontSize = 64;
        ammoLabel.style.unityFontStyleAndWeight = FontStyle.Bold;
        ammoLabel.style.color = Color.white;
        panel.Add(ammoLabel);

        hintLabel = new Label();
        hintLabel.style.fontSize = 24;
        hintLabel.style.color = new Color(1f, 0.4f, 0.4f, 1f);
        panel.Add(hintLabel);

        flasher = root.schedule.Execute(Flash).Every(250);
        flasher.Pause();

        current = magazineSize;
        SetAmmo(current, magazineSize);
    }

    public void SetAmmo(int currentAmmo, int maxAmmo)
    {
        current = currentAmmo;
        ammoLabel.text = currentAmmo + " / " + maxAmmo;
        bool needsReload = currentAmmo <= Mathf.CeilToInt(maxAmmo * lowAmmoFraction);
        hintLabel.text = needsReload ? (currentAmmo == 0 ? "EMPTY - PRESS R" : "RELOAD") : string.Empty;
        if (needsReload)
        {
            flasher.Resume();
        }
        else
        {
            flasher.Pause();
            flashOn = false;
            ammoLabel.style.color = Color.white;
        }
    }

    private void Flash()
    {
        flashOn = !flashOn;
        ammoLabel.style.color = flashOn ? new Color(1f, 0.15f, 0.15f, 1f) : Color.white;
    }

    private void Update()
    {
        if (reloadTimer > 0f)
        {
            reloadTimer -= Time.deltaTime;
            if (reloadTimer <= 0f) SetAmmo(magazineSize, magazineSize);
            return;
        }

        if (Input.GetMouseButtonDown(0) && current > 0) SetAmmo(current - 1, magazineSize);
        if (Input.GetKeyDown(KeyCode.R) && current < magazineSize)
        {
            reloadTimer = reloadTime;
            hintLabel.text = "RELOADING...";
        }
    }
}
```

Other weapon scripts call `SetAmmo(current, max)` whenever the magazine changes. At 25% or below the repeating scheduler toggles the number between red and white every 250 ms, and it is paused again after a reload. The built-in mouse/R handling is only there so the HUD can be tested on its own.

**Plan**
- A static `DamageNumbers.Spawn(position, amount)` creates a world-space TextMesh object at the hit point.
- Every frame the text rotates to face the camera, rises and fades its alpha to zero over its lifetime, then destroys itself.
- A test key spawns numbers above this object so the effect can be seen without enemies.

```csharp
using UnityEngine;

public class FloatingDamageText : MonoBehaviour
{
    private TextMesh textMesh;
    private float age;
    private float lifetime;
    private float riseSpeed;
    private Color baseColor;

    public static FloatingDamageText Spawn(Vector3 worldPosition, int amount)
    {
        GameObject go = new GameObject("DamageNumber");
        go.transform.position = worldPosition + new Vector3(Random.Range(-0.3f, 0.3f), 0f, Random.Range(-0.3f, 0.3f));

        Font font = Font.CreateDynamicFontFromOSFont("Arial", 64);
        TextMesh mesh = go.AddComponent<TextMesh>();
        mesh.font = font;
        mesh.text = amount.ToString();
        mesh.fontSize = 64;
        mesh.characterSize = 0.08f;
        mesh.anchor = TextAnchor.MiddleCenter;
        mesh.alignment = TextAlignment.Center;
        mesh.color = new Color(1f, 0.35f, 0.2f, 1f);
        go.GetComponent<MeshRenderer>().sharedMaterial = font.material;

        FloatingDamageText floating = go.AddComponent<FloatingDamageText>();
        floating.textMesh = mesh;
        floating.baseColor = mesh.color;
        floating.lifetime = 1.0f;
        floating.riseSpeed = 1.6f;
        return floating;
    }

    private void LateUpdate()
    {
        age += Time.deltaTime;
        if (age >= lifetime)
        {
            Destroy(gameObject);
            return;
        }

        transform.position += Vector3.up * (riseSpeed * Time.deltaTime);

        Camera cam = Camera.main;
        if (cam != null)
        {
            transform.rotation = cam.transform.rotation;
        }

        float t = age / lifetime;
        Color c = baseColor;
        c.a = 1f - t * t;
        textMesh.color = c;
        float scale = Mathf.Lerp(1.3f, 0.9f, t);
        transform.localScale = new Vector3(scale, scale, scale);
    }
}

public class DamageNumberTester : MonoBehaviour
{
    [SerializeField] private KeyCode testKey = KeyCode.F;
    [SerializeField] private float heightOffset = 2.2f;

    private void Update()
    {
        if (Input.GetKeyDown(testKey))
        {
            FloatingDamageText.Spawn(transform.position + Vector3.up * heightOffset, Random.Range(5, 60));
        }
    }
}
```

