- Display the score with thousands separators and include a test key for adding points.

```csharp
using UnityEngine;
using UnityEngine.UIElements;

public class ScoreDisplayUI : MonoBehaviour
{
    [SerializeField] private float popScale = 1.5f;
    [SerializeField] private float popDuration = 0.25f;

    private Label scoreLabel;
    private IVisualElementScheduledItem popAnimation;
    private float popElapsed;
    private int score;

    public int Score { get { return score; } }

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.pickingMode = PickingMode.Ignore;
        root.style.alignItems = Align.Center;

        scoreLabel = new Label();
        scoreLabel.style.marginTop = 24;
        scoreLabel.style.fontSize = 56;
        scoreLabel.style.unityFontStyleAndWeight = FontStyle.Bold;
        scoreLabel.style.color = Color.white;
        scoreLabel.style.scale = new Scale(Vector3.one);
        root.Add(scoreLabel);

        popAnimation = scoreLabel.schedule.Execute(AnimatePop).Every(16);
        popAnimation.Pause();
        Refresh();
    }

    public void AddScore(int amount)
    {
        if (amount <= 0) return;
        score += amount;
        Refresh();
        StartPop();
    }

    public void ResetScore()
    {
        score = 0;
        Refresh();
    }

    private void Refresh()
    {
        scoreLabel.text = "SCORE  " + score.ToString("N0");
    }

    private void StartPop()
    {
        popElapsed = 0f;
        scoreLabel.style.scale = new Scale(new Vector3(popScale, popScale, 1f));
        popAnimation.Resume();
    }

    private void AnimatePop()
    {
        popElapsed += Time.unscaledDeltaTime;
        float t = Mathf.Clamp01(popElapsed / popDuration);
        float eased = 1f - (1f - t) * (1f - t);
        float s = Mathf.Lerp(popScale, 1f, eased);
        scoreLabel.style.scale = new Scale(new Vector3(s, s, 1f));
        if (t >= 1f) popAnimation.Pause();
    }

    private void Update()
    {
        if (Input.GetKeyDown(KeyCode.Space)) AddScore(Random.Range(10, 250));
    }
}
```

Every call to `AddScore` bumps the label to 1.5x scale and a 16 ms scheduled callback eases it back to normal over a quarter second, then pauses itself. Using the label's own scheduler means the animation needs no coroutine and keeps working when the game is paused. Space adds random points for testing.

