        prompt.style.borderTopLeftRadius = 10;
        prompt.style.borderTopRightRadius = 10;
        prompt.style.borderBottomLeftRadius = 10;
        prompt.style.borderBottomRightRadius = 10;
        prompt.style.display = DisplayStyle.None;
        root.Add(prompt);

        if (viewCamera == null) viewCamera = Camera.main;
    }

    private void Update()
    {
        Interactable found = null;
        if (viewCamera != null)
        {
            Ray ray = new Ray(viewCamera.transform.position, viewCamera.transform.forward);
            RaycastHit hit;
            if (Physics.Raycast(ray, out hit, maxDistance, hitMask, QueryTriggerInteraction.Ignore))
            {
                found = hit.collider.GetComponentInParent<Interactable>();
            }
        }

        if (found != current)
        {
            current = found;
            if (current != null)
            {
                prompt.text = "Press " + interactKey + " to " + current.actionText;
                prompt.style.display = DisplayStyle.Flex;
            }
            else
            {
                prompt.style.display = DisplayStyle.None;
            }
        }

        if (current != null && Input.GetKeyDown(interactKey))
        {
            current.Interact(gameObject);
        }
    }
}
```

Add `Interactable` to any object with a collider and set its action text, for example "open the door". The prompt script casts a ray from the camera for 3 metres, shows the text only while an interactable is hit, and updates the text only when the target changes. Pressing E invokes the target's `Interacted` event so each object decides what happens.

