using UnityEngine;
using UnityEngine.UIElements;

public class RaceTimerHUD : MonoBehaviour
{
    [SerializeField] private int totalLaps = 3;
    [SerializeField] private bool autoStart = true;

    private Label currentLabel;
    private Label bestLabel;
    private Label lapLabel;
    private float lapTime;
    private float bestTime = -1f;
    private int lapsCompleted;
    private bool running;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.pickingMode = PickingMode.Ignore;

        VisualElement panel = new VisualElement();
        panel.style.position = Position.Absolute;
        panel.style.left = 30;
        panel.style.top = 30;
        panel.style.paddingLeft = 20;
        panel.style.paddingRight = 20;
        panel.style.paddingTop = 12;
        panel.style.paddingBottom = 12;
        panel.style.backgroundColor = new Color(0f, 0f, 0f, 0.6f);
        panel.style.borderTopLeftRadius = 10;
        panel.style.borderTopRightRadius = 10;
        panel.style.borderBottomLeftRadius = 10;
        panel.style.borderBottomRightRadius = 10;
        root.Add(panel);

        lapLabel = MakeLabel(panel, 30, Color.white);
        currentLabel = MakeLabel(panel, 44, Color.white);
        bestLabel = MakeLabel(panel, 26, new Color(1f, 0.85f, 0.3f, 1f));

        lapTime = 0f;
        lapsCompleted = 0;
        bestTime = -1f;
        running = autoStart;
        Refresh();
    }

    private static Label MakeLabel(VisualElement parent, int size, Color color)
    {
        Label label = new Label();
        label.style.fontSize = size;
        label.style.color = color;
        label.style.unityFontStyleAndWeight = FontStyle.Bold;
        parent.Add(label);
        return label;
    }

    public void StartRace()
    {
        lapTime = 0f;
        lapsCompleted = 0;
        running = true;
    }

    public void CompleteLap()
    {
        if (!running) return;
        if (bestTime < 0f || lapTime < bestTime) bestTime = lapTime;
        lapsCompleted++;
        lapTime = 0f;
        if (lapsCompleted >= totalLaps) running = false;
    }

    private static string Format(float seconds)
    {
        int minutes = (int)(seconds / 60f);
        float rest = seconds - minutes * 60f;
        return minutes + ":" + rest.ToString("00.000");
    }

    private void Refresh()
    {
        int shownLap = Mathf.Min(lapsCompleted + 1, totalLaps);
        lapLabel.text = "LAP " + shownLap + " / " + totalLaps;
        currentLabel.text = Format(lapTime);
        bestLabel.text = "BEST  " + (bestTime < 0f ? "--:--.---" : Format(bestTime));
    }

    private void Update()
    {
        if (running) lapTime += Time.deltaTime;
        if (Input.GetKeyDown(KeyCode.Return)) CompleteLap();
        Refresh();
    }
}
```

A finish-line trigger calls `CompleteLap()`: the lap time is compared with the best, the lap counter increases and the timer restarts, and after the final lap the clock stops. Times are formatted as minutes:seconds.milliseconds and refreshed every frame. Enter completes a lap for testing.

**Plan**
- Define an `ItemDefinition` ScriptableObject (name, max stack, weight, icon) and a serializable `ItemStack`.
- A list-based `Inventory` component adds items by topping up existing stacks first, then creating new stacks until capacity is reached, and returns the leftover.
- It also supports Remove, Count and an `OnChanged` event; if no starting items are set it creates a demo item at runtime.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

// Tip: move ItemDefinition into its own ItemDefinition.cs file to create item assets from Assets > Create > Inventory > Item.
[CreateAssetMenu(fileName = "NewItem", menuName = "Inventory/Item")]
public class ItemDefinition : ScriptableObject
{
    public string displayName = "Item";
    [Min(1)] public int maxStack = 20;
    public float weight = 1f;
    public Sprite icon;

    public static ItemDefinition Create(string name, int maxStack, float weight)
    {
        ItemDefinition def = CreateInstance<ItemDefinition>();
        def.name = name;
        def.displayName = name;
        def.maxStack = Mathf.Max(1, maxStack);
        def.weight = weight;
        return def;
    }
}

[Serializable]
public class ItemStack
{
    public ItemDefinition item;
    public int count;

    public ItemStack(ItemDefinition item, int count)
    {
        this.item = item;
        this.count = count;
    }
}

public class Inventory : MonoBehaviour
{
    [SerializeField] private int capacity = 12;
    [SerializeField] private List<ItemStack> startingItems = new List<ItemStack>();

    private readonly List<ItemStack> stacks = new List<ItemStack>();

    public event Action OnChanged;
    public IReadOnlyList<ItemStack> Stacks { get { return stacks; } }
    public int Capacity { get { return capacity; } }

    private void Awake()
    {
        if (startingItems.Count == 0)
        {
            startingItems.Add(new ItemStack(ItemDefinition.Create("Wood", 20, 1f), 45));
        }
        foreach (ItemStack start in startingItems)
        {
            if (start.item != null) Add(start.item, start.count);
        }
    }

    /// <summary>Adds items and returns how many did not fit.</summary>
    public int Add(ItemDefinition item, int amount)
    {
        if (item == null || amount <= 0) return amount;
        int remaining = amount;

        foreach (ItemStack stack in stacks)
        {
            if (stack.item != item || stack.count >= item.maxStack) continue;
            int moved = Mathf.Min(item.maxStack - stack.count, remaining);
            stack.count += moved;
            remaining -= moved;
            if (remaining == 0) break;
        }

        while (remaining > 0 && stacks.Count < capacity)
        {
            int moved = Mathf.Min(item.maxStack, remaining);
            stacks.Add(new ItemStack(item, moved));
            remaining -= moved;
        }

        if (remaining != amount) RaiseChanged();
        return remaining;
    }

    public int Count(ItemDefinition item)
    {
        int total = 0;
        foreach (ItemStack stack in stacks)
        {
            if (stack.item == item) total += stack.count;
        }
        return total;
    }

    public bool Remove(ItemDefinition item, int amount)
    {
        if (item == null || amount <= 0 || Count(item) < amount) return false;
        int remaining = amount;
        for (int i = stacks.Count - 1; i >= 0 && remaining > 0; i--)
        {
            if (stacks[i].item != item) continue;
            int taken = Mathf.Min(stacks[i].count, remaining);
            stacks[i].count -= taken;
            remaining -= taken;
            if (stacks[i].count == 0) stacks.RemoveAt(i);
        }
        RaiseChanged();
        return true;
    }

    private void RaiseChanged()
    {
        if (OnChanged != null) OnChanged();
    }
}
```

Each ItemDefinition decides its own stack size, and `Add` first tops up partially filled stacks, then opens new ones until capacity is reached, returning whatever did not fit so a caller can leave it on the ground. Remove checks the total first so it is all-or-nothing, and every successful change raises `OnChanged` for UI. Move ItemDefinition to its own file if you want to create item assets in the editor.

