            slot.style.alignItems = Align.Center;
            slot.style.justifyContent = Justify.Center;
            SetBorder(slot, 3, new Color(0.35f, 0.38f, 0.45f, 1f));

            Label number = new Label((i + 1).ToString());
            number.style.position = Position.Absolute;
            number.style.left = 5;
            number.style.top = 2;
            number.style.fontSize = 16;
            number.style.color = new Color(0.75f, 0.78f, 0.85f, 1f);
            slot.Add(number);

            Label nameLabel = new Label();
            nameLabel.style.fontSize = 16;
            nameLabel.style.color = Color.white;
            slot.Add(nameLabel);

            slots[i] = slot;
            slotLabels[i] = nameLabel;
            bar.Add(slot);
        }
        Refresh();
    }

    private static void SetBorder(VisualElement element, float width, Color color)
    {
        element.style.borderTopWidth = width;
        element.style.borderBottomWidth = width;
        element.style.borderLeftWidth = width;
        element.style.borderRightWidth = width;
        element.style.borderTopColor = color;
        element.style.borderBottomColor = color;
        element.style.borderLeftColor = color;
        element.style.borderRightColor = color;
    }

    private void Update()
    {
        float scroll = Input.mouseScrollDelta.y;
        if (scroll > 0f) Select((selected - 1 + SlotCount) % SlotCount);
        else if (scroll < 0f) Select((selected + 1) % SlotCount);

        for (int i = 0; i < SlotCount; i++)
        {
            if (Input.GetKeyDown(KeyCode.Alpha1 + i)) Select(i);
        }
    }

    public void Select(int index)
    {
        if (index < 0 || index >= SlotCount || index == selected) return;
        selected = index;
        Refresh();
        if (OnSelectionChanged != null) OnSelectionChanged(selected);
    }

    private void Refresh()
    {
        for (int i = 0; i < SlotCount; i++)
        {
            slotLabels[i].text = i < itemNames.Length ? itemNames[i] : string.Empty;
            SetBorder(slots[i], i == selected ? 5f : 3f, i == selected ? new Color(1f, 0.82f, 0.25f, 1f) : new Color(0.35f, 0.38f, 0.45f, 1f));
        }
        string active = selected < itemNames.Length ? itemNames[selected] : string.Empty;
        activeLabel.text = string.IsNullOrEmpty(active) ? string.Empty : active;
    }
}
```

The wheel moves the selection up or down with wrap-around, number keys jump straight to a slot, and both go through `Select` so the event and highlight stay consistent. Other scripts subscribe to `OnSelectionChanged` and read `SelectedItem` to equip whatever the slot holds. Slot names come from the inspector array.

