public class Ingredient
{
    public ItemDefinition item;
    public int amount = 1;
}

[CreateAssetMenu(menuName = "Crafting/Recipe")]
public class RecipeDefinition : ScriptableObject
{
    public string recipeName = "Recipe";
    public List<Ingredient> ingredients = new List<Ingredient>();
    public ItemDefinition result;
    public int resultAmount = 1;
}

public class CraftInventory : MonoBehaviour
{
    private readonly Dictionary<ItemDefinition, int> counts = new Dictionary<ItemDefinition, int>();

    public int Count(ItemDefinition item)
    {
        int value;
        return counts.TryGetValue(item, out value) ? value : 0;
    }

    public void Add(ItemDefinition item, int amount)
    {
        if (item == null || amount <= 0) return;
        counts[item] = Count(item) + amount;
    }

    public bool Remove(ItemDefinition item, int amount)
    {
        if (item == null || amount <= 0 || Count(item) < amount) return false;
        counts[item] = Count(item) - amount;
        return true;
    }
}

public class CraftingSystem : MonoBehaviour
{
    [SerializeField] private CraftInventory inventory;
    [SerializeField] private List<RecipeDefinition> recipes = new List<RecipeDefinition>();
    [SerializeField] private List<Ingredient> startingMaterials = new List<Ingredient>();

    public event Action<RecipeDefinition> OnCrafted;

    private void Awake()
    {
        if (inventory == null) inventory = GetComponent<CraftInventory>();
        if (inventory == null) inventory = gameObject.AddComponent<CraftInventory>();
        foreach (Ingredient material in startingMaterials)
        {
            inventory.Add(material.item, material.amount);
        }
    }

    public bool CanCraft(RecipeDefinition recipe)
    {
        if (recipe == null || recipe.result == null) return false;
        foreach (Ingredient ingredient in recipe.ingredients)
        {
            if (inventory.Count(ingredient.item) < ingredient.amount) return false;
        }
        return true;
    }

    public bool TryCraft(RecipeDefinition recipe)
    {
        if (!CanCraft(recipe))
        {
            Debug.Log("Cannot craft " + (recipe != null ? recipe.recipeName : "null") + ": missing ingredients");
            return false;
        }

        foreach (Ingredient ingredient in recipe.ingredients)
        {
            inventory.Remove(ingredient.item, ingredient.amount);
        }
        inventory.Add(recipe.result, recipe.resultAmount);
        Debug.Log("Crafted " + recipe.recipeName + " x" + recipe.resultAmount);
        if (OnCrafted != null) OnCrafted(recipe);
        return true;
    }

    private void Update()
    {
        if (Input.GetKeyDown(KeyCode.C) && recipes.Count > 0) TryCraft(recipes[0]);
    }
}
```

Recipes are data: a list of ingredient item/amount pairs plus a result. `TryCraft` checks every ingredient before touching the inventory, so a failed craft never consumes anything, then removes the ingredients, adds the result and raises `OnCrafted`. Assign recipes and starting materials in the inspector and press C to craft the first recipe.

**Plan**
- Define an `EquipSlot` enum (Helmet, Armor, Weapon), a serializable `EquipmentItem` with stat bonuses, and a `PlayerStats` component holding base stats and totals.
- `Equipment` keeps one item per slot; Equip replaces the old item (returning it), Unequip clears the slot.
- After every change the equipment recomputes bonus totals and pushes them to PlayerStats, which raises an event.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

public enum EquipSlot { Helmet, Armor, Weapon }

[Serializable]
public class EquipmentItem
{
    public string itemName = "Item";
    public EquipSlot slot = EquipSlot.Helmet;
    public int bonusHealth;
    public int bonusDefense;
    public int bonusDamage;
}

public class PlayerStats : MonoBehaviour
{
    [SerializeField] private int baseHealth = 100;
    [SerializeField] private int baseDefense = 5;
    [SerializeField] private int baseDamage = 10;

    private int bonusHealth, bonusDefense, bonusDamage;

    public event Action OnStatsChanged;
    public int MaxHealth { get { return baseHealth + bonusHealth; } }
    public int Defense { get { return baseDefense + bonusDefense; } }
    public int Damage { get { return baseDamage + bonusDamage; } }

    public void SetBonuses(int health, int defense, int damage)
    {
        bonusHealth = health;
        bonusDefense = defense;
        bonusDamage = damage;
        if (OnStatsChanged != null) OnStatsChanged();
    }
}

public class Equipment : MonoBehaviour
{
    [SerializeField] private PlayerStats stats;
    [SerializeField] private List<EquipmentItem> demoItems = new List<EquipmentItem>
    {
        new EquipmentItem { itemName = "Iron Helm", slot = EquipSlot.Helmet, bonusHealth = 20, bonusDefense = 3 },
        new EquipmentItem { itemName = "Chain Mail", slot = EquipSlot.Armor, bonusHealth = 40, bonusDefense = 8 },
        new EquipmentItem { itemName = "Steel Sword", slot = EquipSlot.Weapon, bonusDamage = 18 },
    };

    private readonly Dictionary<EquipSlot, EquipmentItem> equipped = new Dictionary<EquipSlot, EquipmentItem>();

    public event Action<EquipSlot, EquipmentItem> OnSlotChanged;

    private void Awake()
    {
        if (stats == null) stats = GetComponent<PlayerStats>();
    }

    private void Start()
    {
        foreach (EquipmentItem item in demoItems) Equip(item);
    }

    public EquipmentItem GetItem(EquipSlot slot)
    {
        EquipmentItem item;
        return equipped.TryGetValue(slot, out item) ? item : null;
    }

    /// <summary>Equips the item and returns whatever was in that slot before (or null).</summary>
    public EquipmentItem Equip(EquipmentItem item)
    {
        if (item == null) return null;
        EquipmentItem previous = GetItem(item.slot);
        equipped[item.slot] = item;
        Recalculate(item.slot, item);
        return previous;
    }

    public EquipmentItem Unequip(EquipSlot slot)
    {
        EquipmentItem previous = GetItem(slot);
        if (previous == null) return null;
        equipped.Remove(slot);
        Recalculate(slot, null);
        return previous;
    }

    private void Recalculate(EquipSlot changedSlot, EquipmentItem newItem)
    {
        int health = 0, defense = 0, damage = 0;
        foreach (KeyValuePair<EquipSlot, EquipmentItem> pair in equipped)
        {
            health += pair.Value.bonusHealth;
            defense += pair.Value.bonusDefense;
            damage += pair.Value.bonusDamage;
        }
        if (stats != null) stats.SetBonuses(health, defense, damage);
        if (OnSlotChanged != null) OnSlotChanged(changedSlot, newItem);
    }
}
```

Bonuses are never added or subtracted incrementally; every change recomputes the totals from whatever is equipped in the three slots, so swapping and unequipping can never leave stale stats. `Equip` returns the replaced item so the caller can put it back in the inventory. The three demo items are equipped at start so the stat change is visible on `PlayerStats`.

**Plan**
- A small `PickupInventory` component stores item counts for the player.
- `ItemPickup` forces its collider to be a trigger, bobs up and down with a sine wave and spins continuously.
- On trigger enter by an object with a `PickupInventory` (found on the collider or its parents), it adds the item and destroys itself.

```csharp
using System.Collections.Generic;
using UnityEngine;

public class PickupInventory : MonoBehaviour
{
    private readonly Dictionary<string, int> items = new Dictionary<string, int>();

    public IReadOnlyDictionary<string, int> Items { get { return items; } }

    public void Add(string itemName, int amount)
    {
        int current;
        items.TryGetValue(itemName, out current);
        items[itemName] = current + amount;
        Debug.Log("Picked up " + amount + " x " + itemName + " (total " + items[itemName] + ")");
    }
}

[RequireComponent(typeof(Collider))]
public class ItemPickup : MonoBehaviour
{
    [SerializeField] private string itemName = "Coin";
    [SerializeField] private int amount = 1;
    [SerializeField] private float bobHeight = 0.25f;
    [SerializeField] private float bobSpeed = 2f;
    [SerializeField] private float spinSpeed = 90f;

    private Vector3 startPosition;
    private float phase;

    private void Reset()
    {
        GetComponent<Collider>().isTrigger = true;
    }

    private void Awake()
    {
        Collider col = GetComponent<Collider>();
        col.isTrigger = true;
        startPosition = transform.position;
        phase = Random.value * Mathf.PI * 2f;
    }

    private void Update()
    {
        float offset = Mathf.Sin(Time.time * bobSpeed + phase) * bobHeight;
        transform.position = startPosition + new Vector3(0f, offset, 0f);
        transform.Rotate(0f, spinSpeed * Time.deltaTime, 0f, Space.World);
    }

    private void OnTriggerEnter(Collider other)
    {
        PickupInventory inventory = other.GetComponentInParent<PickupInventory>();
        if (inventory == null) return;

        inventory.Add(itemName, amount);
        Destroy(gameObject);
    }
}
```

The pickup animates itself from a stored start position so bobbing never drifts, with a random phase so a row of pickups does not move in lockstep. Entering the trigger looks for a `PickupInventory` on the colliding object or any parent, adds the item, and destroys the pickup, so only objects that can hold items collect it. At least one of the two objects needs a Rigidbody for trigger events to fire.

**Plan**
- A `Chest` holds a list of items. When the player is within range and presses E, it opens a UI Toolkit panel listing its contents with "Take All" and "Close" buttons.
- Take All moves everything into the player's `ChestInventory` (a simple counter) and empties the chest, then refreshes the list.
- E again, or Close, closes the panel; walking away also closes it.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;

[Serializable]
public class ChestItem
