public class Chest : MonoBehaviour
{
    [SerializeField] private Transform player;
    [SerializeField] private float interactRange = 3f;
    [SerializeField] private KeyCode openKey = KeyCode.E;
    [SerializeField] private List<ChestItem> contents = new List<ChestItem>
    {
        new ChestItem { itemName = "Gold Coin", amount = 25 },
        new ChestItem { itemName = "Health Potion", amount = 2 },
        new ChestItem { itemName = "Iron Key", amount = 1 },
    };

    private VisualElement panel;
    private VisualElement list;
    private bool isOpen;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.pickingMode = PickingMode.Ignore;
        root.style.alignItems = Align.Center;
        root.style.justifyContent = Justify.Center;

        panel = new VisualElement();
        panel.style.width = 460;
        panel.style.paddingTop = 20;
        panel.style.paddingBottom = 20;
        panel.style.paddingLeft = 24;
        panel.style.paddingRight = 24;
        panel.style.backgroundColor = new Color(0.12f, 0.1f, 0.08f, 0.95f);
        panel.style.display = DisplayStyle.None;
        root.Add(panel);

        Label title = new Label("Chest");
        title.style.fontSize = 36;
        title.style.color = new Color(1f, 0.85f, 0.4f, 1f);
        title.style.marginBottom = 12;
        panel.Add(title);

        list = new VisualElement();
        panel.Add(list);

        Button takeAll = new Button(TakeAll);
        takeAll.text = "Take All";
        takeAll.style.height = 52;
        takeAll.style.fontSize = 24;
        takeAll.style.marginTop = 14;
        panel.Add(takeAll);

        Button close = new Button(() => SetOpen(false));
        close.text = "Close";
        close.style.height = 44;
        close.style.fontSize = 20;
        panel.Add(close);

        RefreshList();
    }

    private void Update()
    {
        if (player == null) return;
        bool inRange = Vector3.Distance(player.position, transform.position) <= interactRange;
        if (inRange && Input.GetKeyDown(openKey)) SetOpen(!isOpen);
        if (isOpen && !inRange) SetOpen(false);
    }

    private void SetOpen(bool open)
    {
        isOpen = open;
        panel.style.display = open ? DisplayStyle.Flex : DisplayStyle.None;
        if (open) RefreshList();
    }

    private void RefreshList()
    {
        list.Clear();
        if (contents.Count == 0)
        {
            Label empty = new Label("The chest is empty.");
            empty.style.fontSize = 22;
            empty.style.color = Color.gray;
            list.Add(empty);
            return;
        }
        foreach (ChestItem item in contents)
        {
            Label row = new Label(item.itemName + "  x" + item.amount);
            row.style.fontSize = 24;
            row.style.color = Color.white;
            row.style.marginBottom = 4;
            list.Add(row);
        }
    }

    private void TakeAll()
    {
        if (player == null) return;
        ChestInventory inventory = player.GetComponentInParent<ChestInventory>();
        if (inventory == null) inventory = player.gameObject.AddComponent<ChestInventory>();
        foreach (ChestItem item in contents) inventory.Add(item.itemName, item.amount);
        contents.Clear();
        RefreshList();
    }
}
```

Each chest owns its item list, so different chests hold different loot. E within range toggles the panel, which builds one row per item; Take All adds every stack to the player's `ChestInventory` (created on demand), empties the chest and refreshes the panel to show it is empty. Walking out of range closes the panel automatically.

**Plan**
- A `WeightedInventory` component tracks item counts with a per-item weight and a maximum carry weight.
- `TryAdd` computes the new total first and returns false without changing anything if it would exceed the limit.
- A small weight bar built in UI Toolkit shows current/max weight and turns red near the limit.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;

[Serializable]
public class WeightedItem
{
    public string itemName = "Item";
    public float weight = 1f;
}

public class WeightedInventory : MonoBehaviour
{
    [SerializeField] private float maxWeight = 50f;
    [SerializeField] private List<WeightedItem> testItems = new List<WeightedItem>
    {
        new WeightedItem { itemName = "Rock", weight = 8f },
        new WeightedItem { itemName = "Sword", weight = 4f },
        new WeightedItem { itemName = "Apple", weight = 0.5f },
    };

    private readonly Dictionary<string, int> counts = new Dictionary<string, int>();
    private readonly Dictionary<string, float> weights = new Dictionary<string, float>();
    private Label weightLabel;
    private VisualElement fill;
    private int testIndex;

    public event Action OnChanged;
    public float MaxWeight { get { return maxWeight; } }

    public float TotalWeight
    {
        get
        {
            float total = 0f;
            foreach (KeyValuePair<string, int> pair in counts) total += weights[pair.Key] * pair.Value;
            return total;
        }
    }

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.pickingMode = PickingMode.Ignore;

        VisualElement panel = new VisualElement();
        panel.style.position = Position.Absolute;
        panel.style.left = 30;
        panel.style.bottom = 30;
        panel.style.width = 320;
        root.Add(panel);

        weightLabel = new Label();
        weightLabel.style.fontSize = 24;
        weightLabel.style.color = Color.white;
        panel.Add(weightLabel);

        VisualElement back = new VisualElement();
        back.style.height = 16;
        back.style.backgroundColor = new Color(0.15f, 0.15f, 0.2f, 0.9f);
        panel.Add(back);

        fill = new VisualElement();
        fill.style.height = Length.Percent(100);
        back.Add(fill);

        OnChanged += Refresh;
        Refresh();
    }

    private void OnDisable()
    {
        OnChanged -= Refresh;
    }

    public bool TryAdd(string itemName, float itemWeight, int amount)
    {
        if (amount <= 0 || itemWeight < 0f) return false;
        if (TotalWeight + itemWeight * amount > maxWeight + 0.0001f) return false;

        int current;
        counts.TryGetValue(itemName, out current);
        counts[itemName] = current + amount;
        weights[itemName] = itemWeight;
        if (OnChanged != null) OnChanged();
        return true;
    }

    public bool Remove(string itemName, int amount)
    {
        int current;
        if (!counts.TryGetValue(itemName, out current) || amount <= 0 || current < amount) return false;
        if (current == amount) counts.Remove(itemName);
        else counts[itemName] = current - amount;
        if (OnChanged != null) OnChanged();
        return true;
    }

    private void Refresh()
    {
        float total = TotalWeight;
        float ratio = Mathf.Clamp01(total / maxWeight);
        weightLabel.text = "Weight " + total.ToString("0.0") + " / " + maxWeight.ToString("0.0");
        fill.style.width = Length.Percent(ratio * 100f);
        fill.style.backgroundColor = ratio > 0.85f ? new Color(0.9f, 0.2f, 0.2f, 1f) : new Color(0.3f, 0.75f, 0.4f, 1f);
    }

    private void Update()
    {
        if (testItems.Count == 0) return;
        if (Input.GetKeyDown(KeyCode.T))
        {
            WeightedItem item = testItems[testIndex % testItems.Count];
            testIndex++;
            bool added = TryAdd(item.itemName, item.weight, 1);
            Debug.Log(added ? "Added " + item.itemName : "Too heavy to carry " + item.itemName);
        }
    }
}
```

`TryAdd` multiplies the weight by the amount and compares the new total with the limit before it changes any data, so a rejected item leaves the inventory untouched and the caller gets `false` to show a "too heavy" message. The weight bar updates through the same `OnChanged` event and turns red above 85% of capacity. Press T to try adding the sample items.

```csharp
using UnityEngine;
using UnityEngine.UIElements;
using UnityEngine.SceneManagement;

public class ScoreAttackManager : MonoBehaviour
{
    public int targetScore = 1000;
    private int currentScore = 0;
    private Label scoreLabel;
    private VisualElement gameOverContainer;

    private void OnEnable()
    {
        var doc = GetComponent<UIDocument>();
        var root = doc.rootVisualElement;
        root.Clear();

        scoreLabel = new Label($"Score: {currentScore} / {targetScore}");
        scoreLabel.style.fontSize = 24;
        scoreLabel.style.color = Color.white;
        root.Add(scoreLabel);

        gameOverContainer = new VisualElement();
        gameOverContainer.style.display = DisplayStyle.None;
        var winLabel = new Label("Target Score Reached!");
        var restartBtn = new Button(() => SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex)) { text = "Play Again" };
        gameOverContainer.Add(winLabel);
        gameOverContainer.Add(restartBtn);
        root.Add(gameOverContainer);
    }

    public void AddScore(int amount)
    {
        currentScore += amount;
        if (scoreLabel != null) scoreLabel.text = $"Score: {currentScore} / {targetScore}";
        if (currentScore >= targetScore && gameOverContainer != null)
        {
            gameOverContainer.style.display = DisplayStyle.Flex;
            Time.timeScale = 0f;
        }
    }
}
```

Manages a score attack mode where score increases trigger UI updates and reaching the target score freezes time and presents a completion screen.
